          '<div class="mc-qa-ask" aria-hidden="true"><span>Ask about this stock…</span><b>Ask</b></div></div><div class="mc-qa-side"><div class="mc-qa-k">SUGGESTED RESEARCH QUESTIONS</div>' +
          t.rows.map(function (r, i) { return '<button type="button" class="mc-qa-s" data-r="' + i + '" aria-pressed="false">' + esc(r.id) + '</button>'; }).join('') + '</div></div>';
