        var magOf = function (i) { return Math.abs(parseFloat(R[i].cells[1].v)) || 1; }, valOf = function (i) { return parseFloat(R[i].cells[2].v) || 1; };
        var up = function (u) { return u ? 'var(--mc-up)' : 'var(--mc-down)'; };
        /* the sector each row belongs to: hovering a sector (or a stock) lights up its sector and its stocks */
        var secOf = function (i) {
          if (i < 19) return i;
          var bull = (i >= 19 && i <= 21) || (i >= 25 && i <= 39), h = hash('mfsec|' + R[i].id) % 10;
          if (bull) return h < 4 ? 15 : h < 7 ? 16 : h % 9;
          return h < 4 ? 17 : h < 7 ? 18 : 9 + (h % 6);
        };
        var btn = function (cls, i, inner, ex) { return '<button type="button" class="' + cls + '" data-r="' + i + '"' + (ex || '') + ' data-sec="' + secOf(i) + '" aria-pressed="false">' + inner + '</button>'; };
        var stockMeta = function (i, rank, bull) {
          var v = valOf(i);
          return ' data-tk="' + esc(R[i].id) + '" data-rank="' + rank + '" data-bull="' + (bull ? 1 : 0) + '" data-px="' + (v * 1.1 + 20).toFixed(2) + '" data-m="' + magOf(i).toFixed(2) + '" data-score="' + (62 + Math.round(v % 34)) + '" data-secn="' + esc(R[secOf(i)].id) + '"';
        };
        var spark = function (i, u) {
          var rr = rng(hash('mfs|' + R[i].id)), d = '', k;
          for (k = 0; k < 14; k++) d += (k ? 'L' : 'M') + (k * 6) + ' ' + (7 - (rr() * 5 + (u ? k * 0.12 : -k * 0.12) + 1)).toFixed(1);
          return '<svg class="mf-sp mc-blur" viewBox="0 0 78 8" preserveAspectRatio="none" aria-hidden="true"><path d="' + d + '" style="fill:none;stroke:' + up(u) + ';stroke-width:1;vector-effect:non-scaling-stroke"/></svg>';
        };
        /* the four index tiles carry the same readings as the Dashboard's market strip */
        var IDXV = { 'S&P 500': ['7,542.32', -0.50], 'NASDAQ': ['25,164.32', -1.07], 'WTI CRUDE': ['96.24', -7.57], 'GOLD': ['3,955.00', 1.44] };
        var idx = ['S&P 500', 'NASDAQ', 'WTI CRUDE', 'GOLD'].map(function (n) {
          var v = IDXV[n], u = v[1] > 0;
          return '<div class="mf-it"><b>' + esc(n) + '</b>' + B(v[0], 'font-size:9.5px;display:block;margin-top:2px') + B((u ? '▲ +' : '▼ ') + v[1].toFixed(2) + '%', 'font-size:7px;display:block;color:' + up(u)) + '</div>';
        }).join('');
        var PULLED = { 0: 1, 14: 1 };
        var secOne = function (n, k) {
          var u = k < 9, m = magOf(k), w = Math.max(8, Math.min(100, m * 28));
          return btn('mf-sr' + (u ? ' is-up' : ' is-dn'), k, '<span class="mf-sn">' + esc(n) + '</span>' + B((u ? '+$' : '-$') + Math.round(valOf(k) * 3) + 'M', 'color:' + up(u)) + B((u ? '+' : '-') + m.toFixed(2) + '%', 'color:var(--mc-text-faint)') + '<i class="mf-sb mc-blur" style="width:' + w + '%;background:' + up(u) + '"></i>');
        };
        /* the app lists sectors by net flow: biggest inflow first, biggest outflow last */
        var secOrder = MF_SECTORS.map(function (n, k) { return k; }).filter(function (k) { return !PULLED[k]; }).sort(function (a, b) {
          var ua = a < 9, ub = b < 9;
          return ua !== ub ? (ua ? -1 : 1) : (ua ? valOf(b) - valOf(a) : valOf(a) - valOf(b));
        });
        var sectors = secOrder.map(function (k) { return secOne(MF_SECTORS[k], k); }).join('');
        var flowCard = function (i, inflow) {
          var m = magOf(i);
          return btn('mf-fc ' + (inflow ? 'is-in' : 'is-out'), i, '<span class="mf-fc-t"><i>' + (inflow ? 'INFLOW' : 'OUTFLOW') + '</i>' + B((inflow ? '+' : '-') + m.toFixed(2) + '%') + '</span><b>' + B(esc(R[i].id)) + '</b>' + B((inflow ? '+$' : '-$') + (valOf(i) / 40 + 1).toFixed(1) + 'B', 'color:' + up(inflow) + ';font-size:10px'));
        };
        var topCards = function (ids, inflow) { return ids.sort(function (a, b) { return valOf(b) - valOf(a); }).map(function (i) { return flowCard(i, inflow); }).join(''); };
        var stockCard = function (i, rank, bull) {
          var m = magOf(i), px = (valOf(i) * 1.1 + 20).toFixed(2), score = 62 + Math.round(valOf(i) % 34), z = function (k) { return B((valOf(i) * (0.8 + k * 0.1)).toFixed(1)); };
          return btn('mf-sc ' + (bull ? 'is-bull' : 'is-bear'), i,
            '<span class="mf-sc-t"><i class="mf-rk">#' + rank + '</i>' + mfLogo(R[i].id) + '<b class="mf-tk">' + B(esc(R[i].id)) + '</b><span class="mf-px">' + B(px) + B((bull ? '+' : '-') + m.toFixed(2) + '%', 'color:' + up(bull)) + '</span><em class="mf-pill">' + (bull ? 'BULLISH' : 'BEARISH') + '</em><i class="mf-ring" style="border-color:' + up(bull) + '">' + B(score) + '</i></span>' +
            '<span class="mf-sc-m"><u>' + (bull ? (rank === 1 ? 'ACCUMULATION' : 'MOMENTUM UP') : (rank === 1 ? 'DISTRIBUTION' : 'MOMENTUM DOWN')) + '</u>' + spark(i, bull) + '</span>' +
            '<span class="mf-sc-z"><u>ZONE</u><u>R2</u><u>R1</u><u>S1</u><u>S2</u><u>R:R</u>' + z(0) + z(1) + z(2) + z(3) + z(4) + z(5) + '</span>', stockMeta(i, rank, bull));
        };
        var tile = function (i, rank, bull) {
          var m = magOf(i);
          return btn('mf-gt ' + (bull ? 'is-bull' : 'is-bear'), i, '<span class="mf-gt-h">' + mfLogo(R[i].id) + '<b>' + B(esc(R[i].id)) + '</b><i class="mf-ring mc-blur" style="border-color:' + up(bull) + '"></i></span><span class="mf-gt-r"><i>#' + rank + '</i> ' +
            B((bull ? '+' : '-') + m.toFixed(2) + '%', 'color:' + up(bull)) + '</span><span class="mf-gt-l"><i>sec</i> ' + B((bull ? '+' : '-') + (m * 0.7).toFixed(2) + '%') + '</span><span class="mf-gt-l"><i>30m</i> ' + B((bull ? '▲' : '▼') + (m * 0.1).toFixed(2) + '%') + '</span><span class="mf-gt-bars mc-blur"></span>', stockMeta(i, rank, bull));
        };
