    labs.forEach(function (t, j) { svg += '<text x="' + f(X0 + j * (X1 - X0) / (labs.length - 1)) + '" y="' + (Y1 + 10) + '" fill="var(--mc-text-faint)" font-size="6" text-anchor="' + (j === 0 ? 'start' : j === labs.length - 1 ? 'end' : 'middle') + '">' + t + '</text>'; });
